// El Error Trigger recibe la ejecucion que ha fallado, no el error pelado.
// Aqui se destila a algo que se pueda leer de un vistazo.
//
// Sin datos del cliente: ni el texto del mensaje, ni el telefono, ni el
// sessionId (bloque 10). Lo que hace falta para arreglar un fallo es el nodo,
// el error y el id de ejecucion; lo demas es mandar datos de alguien a un sitio
// que no los necesita.

const e = $input.first().json;
const wf = e.workflow ?? {};
const ex = e.execution ?? {};
const err = ex.error ?? e.trigger?.error ?? {};

const nodo = ex.lastNodeExecuted ?? err.node?.name ?? 'desconocido';
const mensaje = String(err.message ?? 'sin mensaje').slice(0, 300);

// La huella es lo que hace de antispam en la 0005: el indice unico es
// (nivel, dia local, huella). Con el nodo y el mensaje dentro, un bucle de
// fallos identicos colapsa en UNA fila al dia, y dos fallos distintos se ven
// los dos. Sin ella, un workflow en bucle llena la tabla y el registro deja de
// servir justo cuando mas falta hace.
const huella = (wf.id ?? '?') + ':' + nodo + ':' + mensaje.slice(0, 120);

const partes = [
  'Workflow: ' + (wf.name ?? '?') + ' (' + (wf.id ?? '?') + ')',
  'Nodo: ' + nodo,
  'Error: ' + mensaje,
  'Ejecucion: ' + (ex.id ?? '?'),
];
if (ex.url) partes.push('URL: ' + ex.url);

return [{
  json: {
    nivel: 'ejecucion',
    titulo: 'Ha fallado una ejecucion: ' + nodo,
    detalle: partes.join('\n'),
    contexto: {
      workflow_id: wf.id ?? null,
      workflow: wf.name ?? null,
      nodo: nodo,
      execution_id: ex.id ?? null,
      url: ex.url ?? null,
      modo: ex.mode ?? null,
    },
    huella: huella,
  },
}];
